-- ---------------------------------------------------------------------------
-- --manifest
-- Execution identity and incident parameters.
-- ---------------------------------------------------------------------------
SELECT CURRENT_TIMESTAMP() AS captured_at, '${PROJECT_ID}' AS project_id, '${BQ_DATASET}' AS dataset_id, DATE '${AFFECTED_DATE}' AS affected_date, 19 AS reporting_table_count;

-- ---------------------------------------------------------------------------
-- --table_metadata
-- Table types, creation times, row counts and storage bytes visible to this identity.
-- ---------------------------------------------------------------------------
SELECT t.table_name, t.table_type, t.creation_time, s.row_count, s.size_bytes FROM `${PROJECT_ID}.${BQ_DATASET}.INFORMATION_SCHEMA.TABLES` t LEFT JOIN `${PROJECT_ID}.${BQ_DATASET}.__TABLES__` s ON s.table_id = t.table_name ORDER BY t.table_type, t.table_name;

-- ---------------------------------------------------------------------------
-- --column_partitioning_clustering
-- Partition and clustering metadata visible to this identity.
-- ---------------------------------------------------------------------------
SELECT table_name, column_name, data_type, is_nullable, is_partitioning_column, clustering_ordinal_position FROM `${PROJECT_ID}.${BQ_DATASET}.INFORMATION_SCHEMA.COLUMNS` ORDER BY table_name, ordinal_position;

