SELECT * FROM `${PROJECT_ID}.${BQ_DATASET}.reporting_channel_device_os_a3` WHERE report_date = DATE '${AFFECTED_DATE}' ORDER BY video_id, device_type, operating_system, ingested_at;

-- ---------------------------------------------------------------------------
-- --incident_traffic_rows
-- Every physical row in the affected traffic partition.
-- ---------------------------------------------------------------------------
SELECT * FROM `${PROJECT_ID}.${BQ_DATASET}.reporting_channel_traffic_source_a3` WHERE report_date = DATE '${AFFECTED_DATE}' ORDER BY video_id, traffic_source_type, traffic_source_detail, ingested_at;

-- ---------------------------------------------------------------------------
-- --incident_ledger_rows
-- Complete Reporting ledger history.
-- ---------------------------------------------------------------------------
SELECT * FROM `${PROJECT_ID}.${BQ_DATASET}.reporting_ingest_ledger` ORDER BY report_type, report_date, report_create_time, report_id, ingested_at;

-- ---------------------------------------------------------------------------
-- --incident_device_duplicate_rows
-- Every physical duplicate row using the complete channel_device_os_a3 native grain.
-- ---------------------------------------------------------------------------
SELECT *, COUNT(*) OVER (PARTITION BY report_date, channel_id, video_id, live_or_on_demand, subscribed_status, country_code, device_type, operating_system) AS copies FROM `${PROJECT_ID}.${BQ_DATASET}.reporting_channel_device_os_a3` WHERE report_date = DATE '${AFFECTED_DATE}' QUALIFY copies > 1 ORDER BY report_date, channel_id, video_id, live_or_on_demand, subscribed_status, country_code, device_type, operating_system, ingested_at;

-- ---------------------------------------------------------------------------
-- --incident_device_canonical_copies
-- Canonical physical copies and every ingestion timestamp.
-- ---------------------------------------------------------------------------
SELECT report_date, channel_id, video_id, live_or_on_demand, subscribed_status, country_code, device_type, operating_system, engaged_views, views, watch_time_minutes, average_view_duration_seconds, average_view_duration_percentage, red_views, red_watch_time_minutes, report_id, report_create_time, job_id, load_source, COUNT(*) AS physical_copy_count, ARRAY_AGG(ingested_at ORDER BY ingested_at) AS ingestion_timestamps FROM `${PROJECT_ID}.${BQ_DATASET}.reporting_channel_device_os_a3` WHERE report_date = DATE '${AFFECTED_DATE}' GROUP BY report_date, channel_id, video_id, live_or_on_demand, subscribed_status, country_code, device_type, operating_system, engaged_views, views, watch_time_minutes, average_view_duration_seconds, average_view_duration_percentage, red_views, red_watch_time_minutes, report_id, report_create_time, job_id, load_source ORDER BY report_date, channel_id, video_id, live_or_on_demand, subscribed_status, country_code, device_type, operating_system;

-- ---------------------------------------------------------------------------
-- --incident_traffic_duplicate_rows
-- Every physical duplicate row using the complete channel_traffic_source_a3 native grain.
-- ---------------------------------------------------------------------------
SELECT *, COUNT(*) OVER (PARTITION BY report_date, channel_id, video_id, live_or_on_demand, subscribed_status, country_code, traffic_source_type, traffic_source_detail) AS copies FROM `${PROJECT_ID}.${BQ_DATASET}.reporting_channel_traffic_source_a3` WHERE report_date = DATE '${AFFECTED_DATE}' QUALIFY copies > 1 ORDER BY report_date, channel_id, video_id, live_or_on_demand, subscribed_status, country_code, traffic_source_type, traffic_source_detail, ingested_at;

-- ---------------------------------------------------------------------------
-- --incident_traffic_canonical_copies
-- Canonical physical copies and every ingestion timestamp.
-- ---------------------------------------------------------------------------
SELECT report_date, channel_id, video_id, live_or_on_demand, subscribed_status, country_code, traffic_source_type, traffic_source_detail, engaged_views, views, watch_time_minutes, average_view_duration_seconds, average_view_duration_percentage, red_views, red_watch_time_minutes, report_id, report_create_time, job_id, load_source, COUNT(*) AS physical_copy_count, ARRAY_AGG(ingested_at ORDER BY ingested_at) AS ingestion_timestamps FROM `${PROJECT_ID}.${BQ_DATASET}.reporting_channel_traffic_source_a3` WHERE report_date = DATE '${AFFECTED_DATE}' GROUP BY report_date, channel_id, video_id, live_or_on_demand, subscribed_status, country_code, traffic_source_type, traffic_source_detail, engaged_views, views, watch_time_minutes, average_view_duration_seconds, average_view_duration_percentage, red_views, red_watch_time_minutes, report_id, report_create_time, job_id, load_source ORDER BY report_date, channel_id, video_id, live_or_on_demand, subscribed_status, country_code, traffic_source_type, traffic_source_detail;

-- ---------------------------------------------------------------------------
-- --ledger_duplicates
-- Every report id with more than one physical ledger row.
-- ---------------------------------------------------------------------------
SELECT report_id, ARRAY_AGG(STRUCT(job_id, report_type, report_date, report_create_time, status, row_count, csv_bytes, content_sha256, gcs_uri, load_source, ingested_at, error) ORDER BY ingested_at) AS ledger_rows, COUNT(*) AS physical_rows FROM `${PROJECT_ID}.${BQ_DATASET}.reporting_ingest_ledger` GROUP BY report_id HAVING COUNT(*) > 1 ORDER BY report_id;

-- ---------------------------------------------------------------------------
-- --loaded_generations
-- Jobs and report dates with more than one loaded generation.
-- ---------------------------------------------------------------------------
SELECT job_id, report_date, ARRAY_AGG(STRUCT(report_id, report_create_time, status, ingested_at) ORDER BY report_create_time, ingested_at) AS generations FROM `${PROJECT_ID}.${BQ_DATASET}.reporting_ingest_ledger` WHERE status = 'loaded' GROUP BY job_id, report_date HAVING COUNT(*) > 1 ORDER BY report_date, job_id;

-- ---------------------------------------------------------------------------
-- --ledger_table_mismatches
-- Loaded ledger counts and physical table counts in both directions.
-- ---------------------------------------------------------------------------
WITH t AS (SELECT 'channel_basic_a3' AS report_type, report_id, COUNT(*) AS physical_rows FROM `${PROJECT_ID}.${BQ_DATASET}.reporting_channel_basic_a3` GROUP BY report_id
UNION ALL
SELECT 'channel_province_a3' AS report_type, report_id, COUNT(*) AS physical_rows FROM `${PROJECT_ID}.${BQ_DATASET}.reporting_channel_province_a3` GROUP BY report_id
UNION ALL
SELECT 'channel_playback_location_a3' AS report_type, report_id, COUNT(*) AS physical_rows FROM `${PROJECT_ID}.${BQ_DATASET}.reporting_channel_playback_location_a3` GROUP BY report_id
UNION ALL
SELECT 'channel_traffic_source_a3' AS report_type, report_id, COUNT(*) AS physical_rows FROM `${PROJECT_ID}.${BQ_DATASET}.reporting_channel_traffic_source_a3` GROUP BY report_id
UNION ALL
SELECT 'channel_device_os_a3' AS report_type, report_id, COUNT(*) AS physical_rows FROM `${PROJECT_ID}.${BQ_DATASET}.reporting_channel_device_os_a3` GROUP BY report_id
UNION ALL
SELECT 'channel_subtitles_a3' AS report_type, report_id, COUNT(*) AS physical_rows FROM `${PROJECT_ID}.${BQ_DATASET}.reporting_channel_subtitles_a3` GROUP BY report_id
UNION ALL
SELECT 'channel_combined_a3' AS report_type, report_id, COUNT(*) AS physical_rows FROM `${PROJECT_ID}.${BQ_DATASET}.reporting_channel_combined_a3` GROUP BY report_id
UNION ALL
SELECT 'channel_demographics_a1' AS report_type, report_id, COUNT(*) AS physical_rows FROM `${PROJECT_ID}.${BQ_DATASET}.reporting_channel_demographics_a1` GROUP BY report_id
UNION ALL
SELECT 'channel_sharing_service_a1' AS report_type, report_id, COUNT(*) AS physical_rows FROM `${PROJECT_ID}.${BQ_DATASET}.reporting_channel_sharing_service_a1` GROUP BY report_id
UNION ALL
SELECT 'channel_cards_a1' AS report_type, report_id, COUNT(*) AS physical_rows FROM `${PROJECT_ID}.${BQ_DATASET}.reporting_channel_cards_a1` GROUP BY report_id
UNION ALL
SELECT 'channel_end_screens_a1' AS report_type, report_id, COUNT(*) AS physical_rows FROM `${PROJECT_ID}.${BQ_DATASET}.reporting_channel_end_screens_a1` GROUP BY report_id
UNION ALL
SELECT 'channel_reach_basic_a1' AS report_type, report_id, COUNT(*) AS physical_rows FROM `${PROJECT_ID}.${BQ_DATASET}.reporting_channel_reach_basic_a1` GROUP BY report_id
UNION ALL
SELECT 'channel_reach_combined_a1' AS report_type, report_id, COUNT(*) AS physical_rows FROM `${PROJECT_ID}.${BQ_DATASET}.reporting_channel_reach_combined_a1` GROUP BY report_id
UNION ALL
SELECT 'playlist_basic_a2' AS report_type, report_id, COUNT(*) AS physical_rows FROM `${PROJECT_ID}.${BQ_DATASET}.reporting_playlist_basic_a2` GROUP BY report_id
UNION ALL
SELECT 'playlist_province_a2' AS report_type, report_id, COUNT(*) AS physical_rows FROM `${PROJECT_ID}.${BQ_DATASET}.reporting_playlist_province_a2` GROUP BY report_id
UNION ALL
SELECT 'playlist_playback_location_a2' AS report_type, report_id, COUNT(*) AS physical_rows FROM `${PROJECT_ID}.${BQ_DATASET}.reporting_playlist_playback_location_a2` GROUP BY report_id
UNION ALL
SELECT 'playlist_traffic_source_a2' AS report_type, report_id, COUNT(*) AS physical_rows FROM `${PROJECT_ID}.${BQ_DATASET}.reporting_playlist_traffic_source_a2` GROUP BY report_id
UNION ALL
SELECT 'playlist_device_os_a2' AS report_type, report_id, COUNT(*) AS physical_rows FROM `${PROJECT_ID}.${BQ_DATASET}.reporting_playlist_device_os_a2` GROUP BY report_id
UNION ALL
SELECT 'playlist_combined_a2' AS report_type, report_id, COUNT(*) AS physical_rows FROM `${PROJECT_ID}.${BQ_DATASET}.reporting_playlist_combined_a2` GROUP BY report_id), l AS (SELECT report_type, report_id, row_count FROM `${PROJECT_ID}.${BQ_DATASET}.reporting_ingest_ledger` WHERE status = 'loaded') SELECT COALESCE(l.report_type, t.report_type) AS report_type, COALESCE(l.report_id, t.report_id) AS report_id, l.row_count AS ledger_rows, t.physical_rows AS table_rows FROM l FULL OUTER JOIN t USING (report_type, report_id) WHERE l.report_id IS NULL OR t.report_id IS NULL OR l.row_count != t.physical_rows ORDER BY report_type, report_id;

