-- --incident_device_view_rows
-- Every downstream device view row for the affected date.
-- ---------------------------------------------------------------------------
SELECT * FROM `${PROJECT_ID}.${BQ_DATASET}.channel_device_mix_daily` WHERE report_date = DATE '${AFFECTED_DATE}' ORDER BY video_type, device_type;

-- ---------------------------------------------------------------------------
-- --incident_traffic_view_rows
